function UICommonFilterMB:InitSortTypeList(sortType)
    if self.sortTypeList then return end

    local row = CfUtils.GetCfLine(AutoIds.IdSetting1019, sortType)
    local types = parse_strings(parse_string(row, "type"))
    local sortTypeList = {}
    for i, sortTypeId in ipairs(types) do
        row = CfUtils.GetCfLine(AutoIds.IdSetting1020, sortTypeId)
        local asc = parse_number(row, "condition") <= 0
        local typeDesc = parse_localizeText(row, "typedesc", "")
        local conditionType = parse_number(row, "type")
        table.insert(sortTypeList, {sortTypeId = checkNumber(sortTypeId), asc = asc, typeDesc = typeDesc, conditionType = conditionType, UIType = sortType})
    end

    self.sortTypeList = sortTypeList
end

function UICommonFilterMB:InitSortTypeData(sortTypeData)
    self.sortTypeList = sortTypeData
end

function UICommonFilterMB:InitAlignDropDown(selectIndex)
    if not self.isNeedInitChildList then return end
  
    local parent  = self.alignCellContainer
    parent.Status = self.styleType

    self:InitAlignCellContainerAction()

    local child         = self.AlignCell
    local alignCellList = {}
    local sortTypeList  = self.sortTypeList or {}
    local sortTypeCount = #sortTypeList
    local forTimes      = sortTypeCount
    for i = 1, forTimes do
        local sortTypeData = sortTypeList[i]
        local alignCell    = alignCellList[i]
        if sortTypeData then
            if alignCell == nil then
                alignCell = parent.gameObject:AddChild(child.gameObject)
                alignCellList[i] = alignCell
            end

            ---@type UICommonFilterAlignCell
            local cellEnv = CfUtils.GetLuaScr(alignCell, UICommonFilterAlignCellPath)
            if cellEnv then
                cellEnv:RefreshUI(i, sortTypeData.asc, sortTypeData.typeDesc, self.styleType)
                cellEnv:SetCallback(Bind(self, self.OnClickAlignCellAction))
                cellEnv:RefreshSelectState(selectIndex == i)
            end
            KTool.SetActive(alignCell.gameObject, true)

        elseif alignCell then
            KTool.SetActive(alignCell.gameObject, false)
        end

    end

    self.alignCellList = alignCellList
    self.isNeedInitChildList = nil

end

function UICommonFilterMB:InitAlignCellContainerAction()
    local behaviourAction = KTool.GetOrAddComponent(self.alignCellContainer.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = Bind(self, self.Update)
        self._behaviourAction = behaviourAction
    end
end

function UICommonFilterMB:Update()
    if Utils.TouchCount() > 0 and (not self.__closing) then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local rectTrans = self.pageType == Constants.UIFilterPageType.DropDown and self.DropDownRect or self.PullUPRect
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(rectTrans, position,
                 self.uiRenderCamera or UIModule.RootCanvas.canvas.worldCamera)
            if not isInRect then
                ---不在区域中
                KTool.SetActive(rectTrans.gameObject, false)
            end
        end
    end
end

function UICommonFilterMB:InitAction()
    UIEventProxy.Create(self.AlignButton.gameObject).onPointerClick  = Bind(self, self.OnClickAlignButtonAction)
    UIEventProxy.Create(self.FilterButton.gameObject).onPointerClick = Bind(self, self.OnClickFilterButtonAction)
    UIEventProxy.Create(self.CloseButtonArea.gameObject).onPointerClick  = Bind(self, self.OnCloseFilterButtonAction)
end


