function UICommonFilterMB:RefreshAlignNode(sortTypeData)
    local asc = sortTypeData.asc
    if asc ~= nil then
        local z = asc and 0 or 180
        if self.ImgArrow then
            self.ImgArrow.transform.localEulerAngles = Vector3.New(0, 0, z)
        end
        CfUtils.SetActive(self.ImgArrow, true)
    else
        CfUtils.SetActive(self.ImgArrow, false)
    end
    self:RefreshAlignText(sortTypeData.typeDesc)
end

function UICommonFilterMB:RefreshAlignText(text)
    if self.AlignText then
        CfUtils.FillText(self.AlignText, text)
    else
        CfUtils.FillText(self.Text, text)  -- 不知道为啥，有些绑定的叫 Text
    end
end

function UICommonFilterMB:RefreshCellSelectState(trans, isSelect)
    KTool.SetActive(trans.gameObject, isSelect)
end

function UICommonFilterMB:RefreshUI()
    local sortTypeData = self.sortTypeList[self.selectIndex]
    self:RefreshAlignNode(sortTypeData)

    ---如果是对卡牌等级排序
    if self.callback ~= nil then
        local sortType = sortTypeData.conditionType
        local asc = sortTypeData.asc
        local result = self:SortDataBySortType(sortType, asc, sortTypeData.UIType)
        self.callback(result, true)
    end
    if self.alignCellContainer then
        KTool.SetActive(self.alignCellContainer.gameObject, false)
    end
end

