---@param storeKey string
---@param cb fun(filterData:table):void
function UICommonFilterMB:RestoreState(storeKey, cb)
    local parameter = KCookie.Get(storeKey)
    local sortTypeData
    if isTable(parameter) then
        self.selectIndex = parameter.selectIndex or 1
        sortTypeData     = self.sortTypeList[self.selectIndex]
        local asc        = sortTypeData.asc
        self.groups      = checkTable(parameter.groups)
        self:FreshCloseShowState()
        local sortType   = sortTypeData.conditionType
        if table.count(self.groups) > 0 then
            local dataSet = self.data
            if self.filterClass then
                dataSet = GameUtils.GetScreenData(dataSet, self.groups, self.filterClass, self.extraParams)
            end
            if cb then
                self.filterData = dataSet
                self.filterData = self:SortDataBySortType(sortType, asc, sortTypeData.UIType)
                cb(self.filterData)
            else
                self.filterData = clone(dataSet)
            end
        else
            local filterData = self:SortDataBySortType(sortType, asc, sortTypeData.UIType)
            cb(filterData)
        end
        KCookie.Set(storeKey)
    else
        local dataSet = self.data
        if self.filterClass then
            dataSet = GameUtils.GetScreenData(dataSet, self.groups, self.filterClass, self.extraParams)
        end
        self.filterData = dataSet
        sortTypeData    = self.sortTypeList[self.selectIndex]
        local asc       = sortTypeData.asc
        local sortType  = sortTypeData.conditionType
        self.filterData = self:SortDataBySortType(sortType, asc, sortTypeData.UIType)
        cb(self.filterData)
    end

    self.CloseImage.Status = self.styleType
    self.FilterButton.Status = self.styleType
    self.ImgArrow.Status = self.styleType

    self:RefreshAlignNode(sortTypeData)
end

