---SortDataBySortType
---根据排序类型排序数据
---@param sortType Constants.SortType
function UICommonFilterMB:SortDataBySortType(sortType, asc, UIType)
    if self.customSortCallback then
        return self.customSortCallback(self.filterData or self.data, sortType, asc, UIType)
    end
    if UIType == UISortType.Equip then
        return EquipUtils.SortEquipBackpackData(self.filterData or self.data, sortType, asc)
    elseif UIType == UISortType.EquipCultivate then
        return EquipUtils.SortEquipCultivateBackpackData(self.filterData or self.data, sortType, asc, self.extraParams)
    elseif  UIType == UISortType.CatHouse or
            UIType == UISortType.CatHouseRally or
            UIType == UISortType.CatHouseExplore or
            UIType == UISortType.CatHouseFriend then
        ---@type CatHouseMgr
        local CatHouseMgr = import('Game.CatHouse.CatHouseMgr')
        return CatHouseMgr:GetInstance():SortCat(self.filterData or self.data, sortType, asc, self.extraParams)
    elseif UIType == UISortType.MaidCoffeeCatBallSelect then
        ---@type CatEggComponent
        local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
        return eggComponent:SortCatBall(self.filterData or self.data, sortType, asc, self.extraParams)
    elseif UIType == UISortType.CardEntry then
        ---@type CardProgressionUtils
        local CardProgressionUtils     = import("Game.CardProgression.CardProgressionUtils")
        return CardProgressionUtils.SortEntryBySortType(self.filterData or self.data, sortType, asc, UIType)
    elseif UIType == UISortType.CardTrain then
        return CardUtils.SortCardTrainBySortType(self.filterData or self.data, sortType, asc, UIType)
    elseif UIType == UISortType.MaidCoffee then
        local MaidCoffeeMgr = import('Game.MaidCoffee.MaidCoffeeMgr')
        return MaidCoffeeMgr:GetInstance():SortCardData(self.filterData or self.data, sortType, asc, UIType)
    elseif UIType == UISortType.Convert then
        return self.filterData or self.data
    elseif UIType == UISortType.CatBallChoose then
        ---@type CatBallUtils
        local CatBallUtils                = import("Game.CatBall.CatBallUtils")
        return CatBallUtils.SortCatBallChoose(self.filterData or self.data, sortType, asc, UIType)
    elseif UIType == UISortType.ClubRecord then
        return  ClubUtils.SortBossChallengeRecord(self.filterData or self.data, sortType, asc, UIType)
    else
        if asc == nil and UIType == nil then
            return {}
        else
            return CardUtils.SortCardBySortType(self.filterData or self.data, sortType, asc, UIType, self.customParams)
        end
    end
end

