function UICommonFilterMB:FreshCloseShowState()
    local isShow = self:CheckIsShowCloseBtn()
    -- local isShow = table.count(self.groups) > 0
    KTool.SetActive(self.CloseButton.gameObject, isShow)
    if self.closeButtonStateUpdateCallback then
        self.closeButtonStateUpdateCallback(isShow)
    end
end

function UICommonFilterMB:CheckIsShowCloseBtn()
    local groups     = self.groups
    local defGroups  = self.defGroups
    local groupCount = table.count(groups)
    local isShow     = groupCount > 0
    if not defGroups then
        return isShow
    end

    local function equals(o1, o2, ignore_mt)
        if o1 == o2 then return true end
        local o1Type = type(o1)
        local o2Type = type(o2)
        if o1Type ~= o2Type then return false end
        if o1Type ~= 'table' then return false end
    
        if not ignore_mt then
            local mt1 = getmetatable(o1)
            if mt1 and mt1.__eq then
                --compare using built in method
                return o1 == o2
            end
        end
    
        local keySet = {}
    
        for key1, value1 in pairs(o1) do
            local value2 = o2[key1]
            if value2 == nil or equals(value1, value2, ignore_mt) == false then
                return false
            end
            keySet[key1] = true
        end
    
        for key2, _ in pairs(o2) do
            if not keySet[key2] then return false end
        end
        return true
    end


    return not equals(groups, defGroups)

end

