function UICommonFilterMB:OnClickAlignButtonAction()
    if self.alignCellContainer == nil then
        local parent = self.pageType == Constants.UIFilterPageType.DropDown and self.AlignDropDown or self.AlignPullUP
        self.alignCellContainer = parent
    end
    
    KTool.SetActive(self.alignCellContainer.gameObject, true)
    self:InitAlignDropDown(self.selectIndex)
end

function UICommonFilterMB:OnClickFilterButtonAction()
    if self.filterClass == Constants.UIFilterType.CatHouse then
        UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseFilterPopup, parameters = {
            groups = self.groups,
            geneIdDic = self.geneIdDic,
            cb = function(groups, geneIdDic)
                self.groups    = groups
                self.geneIdDic = geneIdDic
                self:FreshCloseShowState()
                local filterData = GameUtils.GetScreenData(self.data, groups, self.filterClass, self.extraParams, self.geneIdDic)
                -- self.filterData = filterData
                -- if self.callback then
                --     self.filterData = self:Sort()
                --     self.callback(self.filterData, true)
                -- end
                self:SetFilterData(filterData)
            end
        } })
    else
        ---筛选功能按钮
        UIModule.OpenDialog({ id = Constants.UITypeIds.ScreenPanel, parameters = {
            groups = self.groups, defGroups = self.defGroups, filterClass = self.filterClass,
            callBack = function(groups)
                self.groups = groups
                self:FreshCloseShowState()
                local filterData = GameUtils.GetScreenData(self.data, groups, self.filterClass, self.extraParams)
                -- if self.callback then
                --     self.filterData = self:Sort()
                --     self.callback(self.filterData, true)
                -- end
                self:SetFilterData(filterData)
            end
        } })
    end
end

function UICommonFilterMB:OnClickAlignCellAction(index)
    if self.selectIndex == index then return end
    --- 这里只更新 老的cell 选择状态 当前选择状态根据返回值 刷新
    local oldCell = self.alignCellList[self.selectIndex]

    ---@type UICommonFilterAlignCell
    local cellEnv = CfUtils.GetLuaScr(oldCell, UICommonFilterAlignCellPath)
    if cellEnv then
        cellEnv:RefreshSelectState(false)
    end

    self.selectIndex = index

    self:RefreshUI()

    return true
end

function UICommonFilterMB:OnCloseFilterButtonAction()
    if self.sortTypeList == nil then
        return
    end
    self.groups = self.defGroups and clone(self.defGroups) or {}
    self.geneIdDic = {}
    self.filterData = nil
    -- self.selectIndex = 1
    self:FreshCloseShowState()
    self:RefreshUI()
end

